#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
RUNTIME="/etc/hyper-cs16/runtime.json"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-fastdl-amxx-yapb-v1-${STAMP}"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing $SRC_CTL"; exit 2; }
[[ -f "$SRC_UI" ]] || { echo "[ERROR] missing $SRC_UI"; exit 2; }

DOMAIN="www.avito.hyper-host.pw"
if [[ -f "$RUNTIME" ]]; then
  D="$(python3 - "$RUNTIME" <<'PY' 2>/dev/null || true
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding='utf-8'))
    print(str(d.get('domain') or ''))
except Exception:
    pass
PY
)"
  [[ -n "$D" ]] && DOMAIN="$D"
fi
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
cp -a "$SRC_UI" "$BACKUP/index.repo.php"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$LIVE_UI" ]] && cp -a "$LIVE_UI" "$BACKUP/index.live.php"

PATCHER="$(mktemp)"
echo '' | base64 -d > "$PATCHER"

echo "[1/7] Patch repo..."
python3 "$PATCHER" "$SRC_CTL" "$SRC_UI"

echo "[2/7] Syntax checks..."
python3 -m py_compile "$SRC_CTL"
php -l "$SRC_UI" >/dev/null

echo "[3/7] Install live controller..."
install -m 0755 "$SRC_CTL" "$LIVE_CTL"

echo "[4/7] Install live UI..."
if [[ -f "$LIVE_UI" ]]; then
  install -m 0644 "$SRC_UI" "$LIVE_UI"
else
  echo "[WARN] live UI not found: $LIVE_UI"
fi
python3 -m py_compile "$LIVE_CTL"
[[ -f "$LIVE_UI" ]] && php -l "$LIVE_UI" >/dev/null

echo "[5/7] Reload PHP..."
for svc in php8.3-fpm php8.2-fpm php8.1-fpm php8.0-fpm php-fpm; do
  if systemctl list-unit-files "$svc.service" >/dev/null 2>&1; then
    systemctl reload "$svc.service" 2>/dev/null || systemctl restart "$svc.service" 2>/dev/null || true
  fi
done

echo "[6/7] Migrate YaPB current setting for server #$SID..."
STATE="/var/lib/hyper-cs16/servers/${SID}.json"
if [[ -f "$STATE" ]]; then
  read -r Q D < <(python3 - "$STATE" <<'PY'
import json,sys
d=json.load(open(sys.argv[1],encoding='utf-8'))
print(int(d.get('bots_quota') or 9), int(d.get('bots_difficulty') or 3))
PY
)
  "$LIVE_CTL" bots-config "$SID" --quota "$Q" --difficulty "$D" || true
fi

echo "[7/7] Verification..."
echo "--- mods-status ---"
"$LIVE_CTL" mods-status "$SID" || true
echo
echo "--- FastDL status ---"
"$LIVE_CTL" fastdl-status "$SID" || true
echo
echo "--- YaPB cvars ---"
"$LIVE_CTL" rcon "$SID" "yb_quota" || true
"$LIVE_CTL" rcon "$SID" "yb_quota_mode" || true
echo
echo "--- AMXX runtime ---"
"$LIVE_CTL" rcon "$SID" "amxx plugins" || true

rm -f "$PATCHER"

echo
echo "=============================================================="
echo " [SUCCESS] FASTDL / AMXX / YaPB FIX v1 INSTALLED"
echo "=============================================================="
echo "FastDL: Server -> FTP -> Очистить и пересобрать FastDL"
echo "Bots:   Server -> Mods -> Количество ботов (точно)"
echo "Backup: $BACKUP"
